def bank(pr, pc):
    b = [0] * 2048
    for j in range(67):
        for i in range(120):
            if (j & 1) == pr and (i & 1) == pc:
                b[(j >> 1) * 60 + (i >> 1)] = KN[j * 120 + i]
    return b


def rgb(tab, n, signed):
    out = []
    for k in range(n):
        r, g, b = tab[3 * k], tab[3 * k + 1], tab[3 * k + 2]
        out.append(((r & 255) << 16) | ((g & 255) << 8) | (b & 255))
    return out


def arr(name, typ, vals, bits):
    vals = [v & ((1 << bits) - 1) for v in vals]
    rows = []
    for i in range(0, len(vals), 16):
        rows.append("        " + ", ".join('"' + format(v, '0%db' % bits) + '"' for v in vals[i:i + 16]))
    return "    constant %s : %s := (\n" % (name, typ) + ",\n".join(rows) + "\n    );"


def emit():
    de = DE + [0] * (128 - len(DE))
    txt = """-- goblet_pkg.vhd -- GENERATED by goblet.py; edit the generator, not this file.

library ieee;
use ieee.std_logic_1164.all;

package goblet_pkg is
    type t_kb is array(0 to 2047) of std_logic_vector(7 downto 0);
    type t_lut is array(0 to 511) of std_logic_vector(23 downto 0);
    type t_st is array(0 to 255) of std_logic_vector(23 downto 0);
    type t_de is array(0 to 127) of std_logic_vector(7 downto 0);
""" + "\n".join([arr("C_KB00", "t_kb", bank(0, 0), 8), arr("C_KB01", "t_kb", bank(0, 1), 8),
                  arr("C_KB10", "t_kb", bank(1, 0), 8), arr("C_KB11", "t_kb", bank(1, 1), 8),
                  arr("C_GLUT", "t_lut", rgb(LUT, 512, True), 24),
                  arr("C_SE", "t_st", rgb(SE, 256, False), 24), arr("C_SO", "t_st", rgb(SO, 256, False), 24),
                  arr("C_DE", "t_de", de, 8)]) + """
end package goblet_pkg;
"""
    with open(os.path.join(HERE, "goblet_pkg.vhd"), "w") as fh:
        fh.write(txt)


if __name__ == "__main__":
    emit()
